COMMIT;
ALTER TABLE cafe_order AUTO_INCREMENT = 1021;
ALTER TABLE order_detail AUTO_INCREMENT = 2000;
ALTER TABLE outbox AUTO_INCREMENT = 1;
-- =========================================================
-- FEFO 배치 샘플 데이터
-- ingredient_id 1~16 기준, 각 재료마다 2~3개 배치 (유통기한 다르게)
-- =========================================================
CREATE TABLE IF NOT EXISTS stock_batch (
    batch_id      BIGINT       NOT NULL AUTO_INCREMENT,
    ingredient_id INT          NOT NULL,
    order_item_id INT          NULL,
    received_qty  INT          NOT NULL,
    remaining_qty INT          NOT NULL,
    expiry_date   DATE         NULL,
    created_at    DATETIME(6)  NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
    updated_at    DATETIME(6)  NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6),
    PRIMARY KEY (batch_id),
    CONSTRAINT fk_batch_ingredient FOREIGN KEY (ingredient_id) REFERENCES ingredient (ingredient_id)
);

